INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66242903', 66242903, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individual Junior Communication Strategic Specialist Kegiatan Global Environment Facility Indonesia Sustainable Cities Impact Project (GEF INDONESIA SCIP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 179550000, 'February 2026', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '1', '1. Memberikan dukungan keahlian dalam mengumpulkan, mengolah, dan mengemas data serta informasi substantif dan teknis dari seluruh kegiatan PIU GEF Indonesia SCIP menjadi materi komunikasi dan publikasi yang informatif dan mudah dipahami; 2. Membantu menyusun dan mengimplementasikan strategi komunikasi dan diseminasi pengetahuan GEF Indonesia SCIP, termasuk penentuan pesan kunci, target audiens, kanal komunikasi, dan tahapan penyebaran informasi; 3. Membantu mengelola media sosial GEF Indonesia SCIP sebagai platform penyebaran informasi dan pembelajaran kepada publik serta pemangku kepentingan; 4. Memberikan dukungan keahlian dalam melakukan pemantauan media (media monitoring) terhadap pemberitaan dan interaksi di media sosial GEF Indonesia SCIP serta menyusun laporan pemantauan secara berkala; 5. Membantu mengelola dan memperbarui basis data (database) kegiatan seluruh komponen GEF Indonesia SCIP sebagai bagian dari sistem manajemen pengetahuan;', '1. Merupakan jasa konsultan individual dalam negeri, dibuktikan dengan identitas kewarganegaraan Indonesia (KTP). 2. Memiliki NPWP dan status Konfirmasi Status Wajib Pajak (KSWP) yang valid. 3. Memiliki latar belakang pendidikan minimal S1 di bidang Ilmu Komunikasi, Jurnalistik, Hubungan Masyarakat, Media dan Komunikasi, atau bidang lain yang relevan. 4. Memiliki pengalaman kerja minimal 2 (dua) tahun di bidang komunikasi, publikasi, hubungan masyarakat, atau manajemen pengetahuan, khususnya pada program/kegiatan pemerintahan, pembangunan, atau proyek kerja sama internasional, dibuktikan dengan surat keterangan kerja, kontrak, atau referensi pemberi kerja. 5. Memiliki pengalaman dalam perencanaan dan pelaksanaan kegiatan komunikasi dan publikasi, termasuk penyelenggaraan public event, diseminasi kebijakan/program, atau pengelolaan kegiatan komunikasi di lingkungan pemerintahan atau proyek pembangunan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2606961);
