INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66245206', 66245206, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Staf Pengelola Keuangan Hibah Kegiatan Hibah GEF Indonesia Sustainable City Impact Project Direktorat Perumahan dan Infrastruktur Kawasan Permukiman (PIKP)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 92510000, 'January 2026', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '11', '1. Menyusun rencana keuangan proyek berdasarkan Rencana Kerja; 2. Menyusun proyeksi keuangan tiap kuartal dengan tim proyek dan PMU (Unit Manajemen Proyek); 3. Membantu tim proyek untuk memastikan ketersediaan anggaran pada DIPA secara berkala dan memfasilitasi revisi DIPA tepat waktu mengacu ke rencana kerja proyek; 4. Bekerjasama dengan Financial Management Specialist (FMS) di PMU untuk melakukan rekonsiliasi data dalam penyajian laporan Interim Financial Report (IFR) berdasarkan panduan dari PMU; 5. Bekerjasama dengan tim ahli di lingkungan Direktorat PIKP dan tim Project Management Support (PMS)/Project Management Unit (PMU) dalam pelaksanaan kegiatan komponen 2.', '1. Pendidikan minimal D3 Manajemen Keuangan; 2. Memiliki pengalaman kerja profesional minimal 5 (lima) tahun yang berkaitan dengan pengadaan dan pengendalian kontrak proyek-proyek pemerintah dan/atau yang didanai oleh pinjaman dan hibah luar negeri. 3. Memiliki pengalaman dalam berkoordinasi dengan Kementerian/Lembaga dan Pemerintah Daerah. 4. Mempunyai pengalaman dalam pengelolaan keuangan yang dibiayai oleh Pinjaman dan Hibah Luar Negeri 5. Memiliki kemampuan dalam menyusun laporan maupun dokumen secara sistematis; 6. Mampu bekerja dalam tim dan bersedia ditugaskan ke berbagai lokasi untuk keperluan pekerjaan 7. Terbiasa bekerja secara kolaboratif menggunakan layanan penyimpanan awan atau cloud storage. 8. Memliki kemampuan berkomunikasi yang baik dan responsif. 9. Mampu bekerja dalam tim dan bersedia ditugaskan ke berbagai lokasi untuk keperluan pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2609241);
