INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66207980', 66207980, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Pemeliharaan Elevator pada Direktorat Jenderal Kekayaan Intelektual - Provinsi DK Jakarta TA 2026.', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 906067220, 'February 2026', 'APBN - PNBP (D)', 1, 1, '10 Bulan', 'Pekerjaan sehari-hari para pegawai tidak lepas dari mobilitas, baik mobilitas dalam satu area lantai maupun berbeda lantai. Jika ingin berpindah ke lantai yang lain, dibutuhkan sarana tangga ataupun lift/elevator. Tangga dalam prakteknya hanya memungkinkan mengakomodasi mobilitas tidak lebih dari dua lantai. Lebih dari itu pengguna tidak akan menggunakan tangga dan memilih lift dengan alasan energi. Adapun gedung DJKI memiliki 10 lantai sehingga lift menjadi sangat penting dalam menunjang mobilitas pegawai. Lift/elevator adalah alat yang bekerja untuk memperingan, mempercepat pemindahan baik barang ataupun orang. Perawatan yang dilakukan oleh Engineering Elevator berguna untuk menjaga unit transportasi vertikal tetap berfungsi dengan baik, aman dan selalu siap supaya bisa berfungsi dengan baik. Melalui Kegiatan M1 akan dilakukan Pemeliharaan/ Perbaikan/ Penggantian Spare Part Lift yang mencakup pemeliharaan sarana fisik, dari gerbong, sling hingga peralatan elektrik yang melekat pada lift. Di awal masa pemeliharaan, dilakukan pemeriksaan komponen yang perlu diperbaiki serta dinilai tingkat kegentingannya untuk mengatur pelaksanaan penggantian suku cadang/spare part. Dengan kondisi ini , demi efektivitas dan efisiensi peyedia jasa pemeliharaan akan ditunjuk melalui mekanisme Penunjukan Langsung sesuai dengan Perpres 16 tahun 2018 tentang Pengadaan Barang/Jasa Pemerintah', 'Pemeliharaan Gedung DJKI Service 5 (lima) unit LIFT CN : C3NE2265 C3NE2266-C3NE2267C3NE2268 C3NE2269 Termasuk Sparepart (OM)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2609401);
