INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66209837', 66209837, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Pemeliharaan hydrant DJKI Tangerang pada Direktorat Jenderal Kekayaan Intelektual - Provinsi DK Jakarta TA 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 189625000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '10 Bulan', 'Sistem hydrant merupakan salah satu komponen utama dalam sistem proteksi kebakaran aktif pada suatu gedung atau bangunan. Sistem ini berfungsi untuk menyediakan sumber air bertekanan yang dapat digunakan dalam upaya pemadaman kebakaran secara cepat dan efektif. Untuk menjamin keandalan dan kesiapan operasional sistem hydrant, perlu dilakukan pemeliharaan rutin dan berkala, baik terhadap komponen mekanikal, elektrikal, maupun jaringan perpipaan dan aksesorinya. Kegiatan pemeliharaan ini bertujuan agar sistem hydrant selalu dalam kondisi siap pakai, sesuai dengan standar keselamatan kebakaran yang berlaku (misalnya SNI 03-1745-2000, NFPA 25, atau peraturan daerah setempat). Fasilitas gedung yang harus dipelihara agar seluruh kegiatan di dalamnya dapat berlangsung dengan baik. Salah satunya adalah perangkat Hydrant. DJKI memiliki fasilitas pompa untuk gedung di Tangerang untuk sistem hydrant. Dengan demikian, perlu diadakan kegiatan tersendiri berupa Pengadaan Pemeliharaan Hydrant Djki Tangerang. Melalui kegiatan ini akan diadakan pemeliharaan hydrant djki tangerang. Pemeliharaan sistem hydrant di kantor DJKI tangerang bertujuan untuk memastikan sistem pemadam kebakaran berfungsi optimal dalam keadaan darurat. Sistem ini meliputi mesin penggerak diesel, motor penggerak listrik, pompa multistages centrifugal, hydrant pillar, hose dan nozzle, pipa dan valve dan control panel yang harus dipelihara secara berkala agar selalu siap digunakan. Pemeliharaan ini penting untuk menjaga keselamatan, mencegah kerusakan, serta meminimalkan risiko kebakaran di kantor.', 'Box Hydrant Damkar Pemadam 1 unit Fire Hydrant Box Type B Kaca Indoor Jet nozzle machino ukuran 1,2 inch 1 unit Fire hose rubber selang 3 unit Seal karet dalam bentuk coupling dan nozzle pemadam machino 1.5 Inch 2 unit Oli mesin diesel 1 liter 2 unit Bearing SKF laher bearing skf 6202 2RS karet motor pompa mesin 2 unit Pekerjaan pengecatan box hydrant 19 unit Pilot lamp lampu indikator panel 5volt 6 unit Jasa pemasangan teknisis 11 unit Panel Hydrant terbaru 1 unit Jasa Pemasangan Teknisi 1 unit', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2609479);
