INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66245693', 66245693, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Institutional and Governance Specialist Kegiatan Hibah GEF Indenesia Sustainable City Impact Project (SCIP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 425000000, 'February 2026', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '17', '1. Melakukan perencanaan, pemantauan, dan pelaporan proyek GEF SCIP di lingkungan PIU Direktorat PIKP khususnya pada aspek kelembagaan dan tata kelola, yang meliputi: a. Menyusun dan mengelola rencana kerja, rencana kegiatan detail dan jadwal kegiatan terkait kelembaggan dan peningkatan tatakelola untuk Komponen 2 di bawah PIU Direktorat PIKP. b. Memantau, mengevaluasi, dan melaporkan kemajuan indikator kinerja proyek khususnya pada aspek peningkatan kapasitas kelembagaan, tata kelola, dan penguatan koordinasi antar pemangku kepentingan secara berkala (bulanan/triwulanan) kepada PIU, PMU, dan pemangku kepentingan terkait. c. Menyusun laporan berkala (triwulanan dan tahunan) serta laporan akhir yang komprehensif dengan analisis mendalam terhadap capaian dan tantangan aspek kelembagaan dan tata kelola untuk Direktorat PIKP sebagai Koordinator PIU (Sesuai KAK)', '1. Pendidikan minimal S2 semua jurusan, dengan pendidikan S1 dari hukum, sosial, politik, manajemen, atau ekonomi . 2. Memiliki pengalaman kerja profesional minimal 8 (delapan) tahun yang berkaitan dengan pengelolaan proyek-proyek pemerintah dan/atau yang didanai oleh pinjaman dan hibah luar negeri dengan tugas terkait aspek kelembagaan pada sektor pengelolaan sampah, air limbah domestik, dan air minum. 3. Memiliki pengalaman di bidang fasilitasi kelembagaan dan/atau pendampingan penyusunan produk perencanaan pembangunan skala daerah maupun nasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2609573);
